// Sales Agent - Handle leads and new clients

const input = $input.first().json;
const body = input.body || input;

const taskId = body.task_id || `sales_${Date.now()}`;
const taskType = body.task_type || 'lead';

// Extract lead info
const lead = {
  task_id: taskId,
  task_type: taskType,
  email: body.from?.email || body.from || body.email || '',
  name: body.from?.name || body.name || '',
  subject: body.subject || '',
  message: body.snippet || body.message || body.description || '',
  source: body.source || 'email',
  timestamp: new Date().toISOString()
};

// Qualify the lead
const message = lead.message.toLowerCase();
let priority = 'normal';
let leadScore = 50;

// High intent signals
if (message.includes('pricing') || message.includes('quote')) {
  priority = 'high';
  leadScore += 20;
}
if (message.includes('asap') || message.includes('urgent') || message.includes('immediately')) {
  priority = 'high';
  leadScore += 15;
}
if (message.includes('budget') || message.includes('ready to start')) {
  leadScore += 25;
}

lead.priority = priority;
lead.lead_score = Math.min(leadScore, 100);

return lead;

// Return completion
const lead = $('Qualify Lead').first().json;

return {
  agent: 'sales',
  status: 'completed',
  lead_email: lead.email,
  lead_score: lead.lead_score,
  priority: lead.priority,
  auto_reply_sent: true,
  timestamp: new Date().toISOString()
};
